DROP POLICY IF EXISTS "Public can submit blood requests with validation" ON public.blood_requests;
CREATE POLICY "Public can submit blood requests with validation" ON public.blood_requests FOR INSERT TO anon, authenticated WITH CHECK ((status = 'pending') AND (char_length(TRIM(BOTH FROM patient_name)) >= 2) AND (blood_group = ANY (ARRAY['A+','A-','B+','B-','AB+','AB-','O+','O-'])) AND (contact_phone ~ '^01[3-9][0-9]{8}$') AND (char_length(TRIM(BOTH FROM hospital)) >= 2) AND (units_needed >= 1) AND (units_needed <= 20) AND ((hemoglobin IS NULL) OR ((hemoglobin >= 1) AND (hemoglobin <= 20))));